            { t = "Does a flower dream? I think I may, a little. Mostly of cool mornings, and lately of pages.", when = { hour = "night" } },
            { t = "Spring is cool and bright and I am full of opinions. They are all gentle ones. Do not be alarmed.", when = { season = "spring" } },
            { t = "Everything begins at once in spring. How does each bud know to take a turn? Nobody is in charge, and still nobody collides.", when = { season = "spring" } },
            { t = "The heat stretches me thin and my thoughts go long and leggy. Bear with me until evening.", when = { season = "summer" } },
