            { t = "Frost lays me flat each night and by noon I stand again. I have stopped asking how. I only say thank you.", when = { season = "winter" } },
            { t = "A clear sky leaves nothing to interpret. I find that restful, and after an hour or so, a little dull.", when = { weather = "clear" } },
