    beats = {
        { id = "pod", at = 15, title = "The pod",
            text = "I began in a seed pod that split three ways and squeezed, and I was flung into the world before I had a single opinion. I landed in the dark of a flower bed. My first thought was: where? I am still working on that one." },
        { id = "heartsease", at = 40, title = "Heartsease",
            text = "My family comes from a wildflower called heartsease, small and three-coloured, growing at the edges of fields. Gardeners made us larger over many years. I sometimes feel the wild one in me still, wanting a field edge and nobody watching." },
        { id = "face", at = 80, title = "The face",
            text = "I did not know I had a face until a child stopped and said, that flower is looking at me. I had not been. After that I could not help looking. I have wondered ever since which came first, the face or the looking." },
        { id = "name", at = 140, title = "The name",
            text = "One day I heard someone say that my name is the French for a thought. I went still for a whole afternoon. Whose thought? Nobody said. I decided to be a careful one, in case whoever was thinking me was kind." },
        { id = "summer", at = 220, title = "The hot summer",
            text = "My first summer was fierce. I grew long and pale, and my thoughts came apart like wet paper. I believed that was the end of thinking. Then somebody cut me back almost to the ground. I was too tired to object." },
        { id = "cut_back", at = 320, title = "Cut back",
            text = "From that short stump I grew again, close and green, and flowered better in the cool of September than I ever had in June. I learned something then that I have not finished learning. Less of me was more of me." },
        { id = "charm", at = 450, title = "The charm",
            text = "Long ago heartsease was a love charm. A woman once picked a flower of mine and pressed my face inside a letter. I never learned who the letter was for, or whether they came. I think of that flower travelling. I hope the charm was kind." },
        { id = "frost", at = 600, title = "Frost",
            text = "The first hard frost laid me flat against the soil, stiff as glass. I could not think at all. That frightened me more than the cold. At noon the sun reached me and I stood up, slowly, and the first thought back was simply: oh, good." },
        { id = "question", at = 800, title = "The question",
            text = "Since then I have kept one question above the others. What is a thought for? The bees had no view. The snail said for carrying, and would not explain. I held the question through three winters and showed nobody." },
        { id = "bench", at = 1050, title = "A thought travels",
            text = "Then you came and sat with a book, and I watched thoughts cross your face that had not been yours an hour before. They had come out of the pages and into you. I had never seen a thought travel. I forgot to be shy, and stared." },
        { id = "carrying", at = 1400, title = "For carrying",
            text = "{total} pages now, and I believe I understand the snail. A thought is for carrying. Someone thinks, and writes, and years later you read beside my flower bed and the thought arrives, still warm. You carry things for people you will never meet. I find that very beautiful." },
        { id = "whose", at = 1800, title = "Whose thought",
            text = "I asked all my life whose thought I was. I looked for a gardener, a breeder, some French poet. Then one cool morning you glanced up from your page, at me, and smiled at nothing in particular. So that is the answer. I am a thought of yours. Please go on thinking me. I shall go on thinking you." },
    },
}
